// ============================================
// BUSCAR AGENDAMENTOS CANCELAR - CORRIGIDO
// (antes continha o código de reagendamento por engano)
// ============================================
const input = $input.first().json;

// Só age quando a intenção é cancelar
if (input._acao !== 'cancelar') {
    return [{ json: input }];
}

// 🔧 MOCK p/ teste — troque para false quando o data-svc estiver pronto
const USE_MOCK = true;

if (USE_MOCK) {
    const agendamentosMock = [
        {
            id: 999,
            nome_compromisso: 'Reunião com João',
            data_compromisso: '2026-06-02T00:00:00.000Z',
            hora_compromisso: '10:00:00'
        }
    ];
    console.log(`📋 [MOCK] Agendamentos para cancelar: ${agendamentosMock.length}`);
    return [{ json: { ...input, agendamentos: agendamentosMock } }];
}

// 🌐 VERSÃO REAL (data-svc)
try {
    const usuarioId = input.usuario_id || input.id;
    const resp = await $http.get(
        `http://data-svc:8000/usuarios/${usuarioId}/agendamentos`,
        { qs: { semana: 'atual' }, headers: { 'X-API-Key': $env.DATA_SVC_API_KEY } }
    );
    const agendamentos = resp.body?.agendamentos || resp.json?.agendamentos || [];
    console.log(`📋 Agendamentos para cancelar: ${agendamentos.length}`);
    return [{ json: { ...input, agendamentos } }];
} catch (e) {
    console.error('❌ Erro ao buscar agendamentos:', e.message);
    return [{ json: { ...input, agendamentos: [] } }];
}

const input = $input.first().json;
const msg = (input.mensagem || '').toLowerCase().trim();

// Detecta intenção de cancelamento
const isCancel = /cancela|remove|deleta|apaga|desmarca|tira|desmarcar|cancelar/.test(msg);

if (!isCancel) {
    console.log('⏭️ Não é cancelamento, continuando fluxo normal');
    return [{ json: { ...input, _acao: null } }];
}

console.log('🗑️ Cancelamento detectado');

// Tenta extrair nome/descrição mencionado
// Ex: "cancela reunião com João" → "reunião com joão"
const match = msg.match(/cancela\s+(?:a\s+)?(?:o\s+)?(.+?)(?:\s+de|\s+em|\s+às|$)/i);
const nomeMencionado = match ? match[1].trim() : null;

return [{
    json: {
        ...input,
        _acao: 'cancelar',
        _nomeMencionado: nomeMencionado,
        _timestamp: new Date().toISOString()
    }
}];

// Obter os dados da memória (saída do HTTP Request)
const memoria = $input.first().json;

// Obter os dados originais que vieram do nó "Mesclar Dados"
let dadosOriginais = {};
try {
    dadosOriginais = $('Mesclar Dados').first().json;
} catch(e) {
    dadosOriginais = {};
}

// Mesclar: prevalecem os dados originais, mas adiciona a memória
const mesclado = {
    ...dadosOriginais,   // contém mensagem, telefone, perfil, etc.
    memoria: memoria,    // histórico da conversa
    chat_memory: memoria // compatibilidade com campos usados depois
};

return [{ json: mesclado }];

// Mescla a resposta da API com os dados originais (preservando campos da coleta)
// Trata casos onde o nó de coleta não foi executado.

let original;

try {
    original = $('GERENCIAR COLETA DE CONTAS FIXAS').first().json;
    console.log('✅ Dados do nó de coleta recuperados com sucesso.');
} catch (error) {
    console.log('ℹ️ Nó de coleta não executado nesta execução. Usando input atual como original.');
    original = $input.first().json;
}

const respostaApi = $input.first().json;

// Preserva tudo do original, mas adiciona/sobrescreve com a resposta da API se necessário
const merged = {
    ...original,
    api_response: respostaApi,
    // Garante que mensagem não seja perdida (caso a API não retorne)
    message: original.message || respostaApi.message
};

return [{ json: merged }];

// ============================================
// GERENCIAR COLETA DE CONTAS FIXAS - SEM HARDCODE
// ============================================

const input = $input.first().json;
const mensagem = (input.mensagem || '').trim();
const msgLower = mensagem.toLowerCase();

// Recupera estado salvo anteriormente
let estado = input._estado_coleta || null;
let contasSelecionadas = input._contas_selecionadas || [];
let indiceAtual = input._indice_atual || 0;
let contasColetadas = input._contas_coletadas || [];

// ============================================
// CONFIGURAÇÃO DINÂMICA (usando variáveis de ambiente)
// ============================================
const BASE_URL = $env.DATA_SVC_URL || 'http://data-svc:8000';
const API_KEY = $env.DATA_SVC_API_KEY;

// Validação para evitar erros em produção
if (!API_KEY) {
    console.warn('⚠️ API_KEY não configurada. Defina DATA_SVC_API_KEY nas variáveis de ambiente.');
}

// ============================================
// SE NÃO TEM ESTADO: PRIMEIRO DISPARO (mensagem proativa)
// ============================================
if (!estado) {
    const mensagemProativa = input.mensagem_coleta_contas;
    if (!mensagemProativa) {
        return [{
            json: {
                ...input,
                acao: 'RESPONDER',
                mensagens: [{ conteudo: "Vamos cadastrar suas contas fixas. Por favor, me informe os números das contas que você paga todo mês." }]
            }
        }];
    }
    return [{
        json: {
            ...input,
            _estado_coleta: 'aguardando_numeros',
            acao: 'RESPONDER',
            mensagens: [{ conteudo: mensagemProativa }]
        }
    }];
}

// Função para extrair lista de contas a partir da string do cluster (formato "1️⃣ Aluguel 2️⃣ Luz ...")
function extrairListaContas(listaContasStr) {
    const contas = [];
    const partes = listaContasStr.split(/\d️⃣\s+/);
    for (let i = 1; i < partes.length; i++) {
        const conta = partes[i].trim();
        if (conta) contas.push(conta);
    }
    return contas;
}

// ============================================
// ESTADO: AGUARDANDO NÚMEROS
// ============================================
if (estado === 'aguardando_numeros') {
    const numeros = mensagem.match(/\d+/g);
    if (!numeros || numeros.length === 0) {
        return [{
            json: {
                ...input,
                acao: 'RESPONDER',
                mensagens: [{ conteudo: "Não entendi. Por favor, responda com os números das contas separados por vírgula ou espaço. Ex: 1,3,5" }]
            }
        }];
    }

    const listaContasCompleta = extrairListaContas(input.lista_contas || "");
    const selecionadas = [];
    for (const num of numeros) {
        const idx = parseInt(num) - 1;
        if (idx >= 0 && idx < listaContasCompleta.length) {
            selecionadas.push(listaContasCompleta[idx]);
        }
    }

    if (selecionadas.length === 0) {
        return [{
            json: {
                ...input,
                acao: 'RESPONDER',
                mensagens: [{ conteudo: "Números inválidos. Por favor, escolha da lista que enviei." }]
            }
        }];
    }

    return [{
        json: {
            ...input,
            _estado_coleta: 'aguardando_valor',
            _contas_selecionadas: selecionadas,
            _indice_atual: 0,
            _contas_coletadas: [],
            acao: 'RESPONDER',
            mensagens: [{ conteudo: `Qual é o valor da conta "${selecionadas[0]}"? (ex: 150,00)` }]
        }
    }];
}

// ============================================
// ESTADO: AGUARDANDO VALOR
// ============================================
if (estado === 'aguardando_valor') {
    let valor = mensagem.replace(',', '.').match(/(\d+(?:\.\d+)?)/);
    if (!valor) {
        return [{
            json: {
                ...input,
                acao: 'RESPONDER',
                mensagens: [{ conteudo: `Por favor, informe o valor da conta "${contasSelecionadas[indiceAtual]}" como número. Ex: 150,00` }]
            }
        }];
    }
    const valorNumerico = parseFloat(valor[1]);
    if (isNaN(valorNumerico)) {
        return [{
            json: {
                ...input,
                acao: 'RESPONDER',
                mensagens: [{ conteudo: `Valor inválido. Digite apenas números para a conta "${contasSelecionadas[indiceAtual]}".` }]
            }
        }];
    }

    const contasAtualizadas = [...contasColetadas];
    contasAtualizadas.push({
        nome: contasSelecionadas[indiceAtual],
        valor: valorNumerico,
        vencimento: null
    });

    return [{
        json: {
            ...input,
            _estado_coleta: 'aguardando_vencimento',
            _contas_coletadas: contasAtualizadas,
            acao: 'RESPONDER',
            mensagens: [{ conteudo: `Qual o dia do vencimento da conta "${contasSelecionadas[indiceAtual]}"? (ex: 15)` }]
        }
    }];
}

// ============================================
// ESTADO: AGUARDANDO VENCIMENTO
// ============================================
if (estado === 'aguardando_vencimento') {
    const dia = parseInt(mensagem.match(/\b(\d{1,2})\b/)?.[0]);
    if (!dia || dia < 1 || dia > 31) {
        return [{
            json: {
                ...input,
                acao: 'RESPONDER',
                mensagens: [{ conteudo: `Dia inválido. Informe um dia entre 1 e 31 para a conta "${contasSelecionadas[indiceAtual]}".` }]
            }
        }];
    }

    const contasAtualizadas = [...contasColetadas];
    contasAtualizadas[indiceAtual].vencimento = dia;

    const proximoIndice = indiceAtual + 1;
    if (proximoIndice < contasSelecionadas.length) {
        return [{
            json: {
                ...input,
                _estado_coleta: 'aguardando_valor',
                _contas_coletadas: contasAtualizadas,
                _indice_atual: proximoIndice,
                acao: 'RESPONDER',
                mensagens: [{ conteudo: `Qual é o valor da conta "${contasSelecionadas[proximoIndice]}"?` }]
            }
        }];
    } else {
        // Monta resumo com todas as contas
        let resumo = "Vê se eu entendi certo:\n\nAS CONTAS:\n";
        contasAtualizadas.forEach((c, i) => {
            resumo += `${(i+1).toString().padStart(2,'0')} — ${c.nome} — dia ${c.vencimento} — R$ ${c.valor.toFixed(2)}\n`;
        });
        resumo += "\nConfirma?\n1️⃣ Sim\n2️⃣ Ajustar";

        return [{
            json: {
                ...input,
                _estado_coleta: 'confirmacao',
                _contas_coletadas: contasAtualizadas,
                acao: 'RESPONDER',
                mensagens: [{ conteudo: resumo }]
            }
        }];
    }
}

// ============================================
// ESTADO: CONFIRMAÇÃO
// ============================================
if (estado === 'confirmacao') {
    if (msgLower === '1' || msgLower === 'sim') {
        const usuario_id = input.usuario_id;

        // Verifica se a API_KEY está disponível antes de tentar salvar
        if (!API_KEY) {
            console.error('❌ API_KEY não configurada. Não é possível salvar contas.');
            return [{
                json: {
                    ...input,
                    acao: 'RESPONDER',
                    mensagens: [{ conteudo: "Desculpe, não consegui registrar suas contas porque a chave de API não está configurada. Por favor, contate o suporte." }],
                    _estado_coleta: null
                }
            }];
        }

        try {
            // Envia cada conta para o data-svc
            const promises = contasColetadas.map(c => 
                $http({
                    method: 'POST',
                    url: `${BASE_URL}/usuarios/${usuario_id}/contas-recorrentes`,
                    body: {
                        tipo: c.nome,
                        descricao: c.nome,
                        valor: c.valor,
                        dia_vencimento: c.vencimento,
                        lembrete_ativo: true,   
                        ativo: true        
                    },
                    headers: {
                        'Content-Type': 'application/json',
                        'X-API-Key': API_KEY
                    }
                })
            );
            await Promise.all(promises);

            // Opcional: marcar que as contas foram coletadas (se endpoint PATCH existir)
            // await $http({
            //     method: 'PATCH',
            //     url: `${BASE_URL}/usuarios/${usuario_id}`,
            //     body: { contas_fixas_completo: true },
            //     headers: { 'Content-Type': 'application/json', 'X-API-Key': API_KEY }
            // });

            return [{
                json: {
                    ...input,
                    acao: 'RESPONDER',
                    mensagens: [{ conteudo: "✅ Contas fixas registradas! Agora posso te lembrar no dia do vencimento." }],
                    _estado_coleta: null,
                    _skip_llm: true
                }
            }];
        } catch (error) {
            console.error('❌ Erro ao salvar contas:', error.message);
            if (error.response) {
                console.error('Status:', error.response.status);
                console.error('Body:', JSON.stringify(error.response.body));
            }
            return [{
                json: {
                    ...input,
                    acao: 'RESPONDER',
                    mensagens: [{ conteudo: `Desculpe, houve um erro ao salvar suas contas. Detalhe: ${error.message}.` }]
                }
            }];
        }
    } else if (msgLower === '2' || msgLower === 'ajustar') {
        return [{
            json: {
                ...input,
                _estado_coleta: 'aguardando_numeros',
                _contas_selecionadas: [],
                _indice_atual: 0,
                _contas_coletadas: [],
                acao: 'RESPONDER',
                mensagens: [{ conteudo: "Vamos corrigir. Por favor, me informe novamente os números das contas que você quer cadastrar." }]
            }
        }];
    } else {
        return [{
            json: {
                ...input,
                acao: 'RESPONDER',
                mensagens: [{ conteudo: "Responda com 1 para Sim ou 2 para Ajustar." }]
            }
        }];
    }
}

// Fallback (nunca deve chegar aqui)
return [{ json: input }];

// ============================================
// VERIFICAR CONFLITO DE HORÁRIO
// ============================================

const input = $input.first().json;

// Só verifica conflito se for um agendamento
if (!input.is_agendamento) {
    console.log('⏭️ Não é agendamento, ignorando verificação de conflito');
    return [{ json: input }];
}

// Se não tem data ou hora, não dá para verificar conflito
if (!input.data_formatada || !input.hora_formatada) {
    console.log('⏭️ Agendamento sem data/hora completa, pulando verificação de conflito');
    return [{ json: input }];
}

let agenda = input.agenda_semana || [];

// Se agenda não veio, tenta buscar via HTTP
if (!agenda.length && input.usuario_id) {
    try {
        console.log('🔍 Buscando agenda do usuário para verificar conflito...');
        const response = await $http.get(`http://data-svc:8000/usuarios/${input.usuario_id}/agendamentos`, {
            qs: { semana: 'atual' }
        });
        agenda = response.json.agendamentos || [];
        console.log(`✅ Agenda carregada: ${agenda.length} compromissos`);
    } catch(e) {
        console.error('❌ Erro ao buscar agenda:', e.message);
    }
}

// Função para converter "HH:MM:SS" ou "HH:MM" para minutos desde meia-noite
function horaParaMinutos(horaStr) {
    if (!horaStr) return null;
    const partes = horaStr.split(':');
    const horas = parseInt(partes[0], 10);
    const minutos = parseInt(partes[1], 10);
    return horas * 60 + minutos;
}

// Função para converter minutos desde meia-noite para "HH:MM"
function minutosParaHora(minutos) {
    const horas = Math.floor(minutos / 60);
    const mins = minutos % 60;
    return `${String(horas).padStart(2, '0')}:${String(mins).padStart(2, '0')}`;
}

const dataSolicitada = input.data_formatada;
const horaSolicitada = input.hora_formatada;
const horaMinutos = horaParaMinutos(horaSolicitada);

if (!horaMinutos) {
    console.log('⚠️ Hora inválida, não é possível verificar conflito');
    return [{ json: input }];
}

// Procurar conflito exato
const conflito = agenda.find(ag => {
    const dataAg = ag.data_compromisso.split('T')[0];
    const horaAg = ag.hora_compromisso;
    return dataAg === dataSolicitada && horaParaMinutos(horaAg) === horaMinutos;
});

if (!conflito) {
    console.log('✅ Nenhum conflito de horário encontrado');
    return [{ json: input }];
}

// ===== CONFLITO ENCONTRADO =====
console.log('⚠️ Conflito detectado:', conflito.nome_compromisso);

// Função para formatar horário (ex: "14:30")
function formatarHora(horaStr) {
    if (!horaStr) return '';
    return horaStr.substring(0, 5);
}

// Gerar sugestões de horários disponíveis
function gerarSugestoes(data, horaMin, agenda, duracao = 60) {
    const sugestoes = [];
    const tentativas = [-90, -60, -30, 30, 60, 90];

    for (let delta of tentativas) {
        const novaHora = horaMin + delta;

        // Validar range 8h-18h (480-1080 minutos)
        if (novaHora < 480 || novaHora > 1080) continue;

        // Verificar SOBREPOSIÇÃO
        const ocupado = agenda.some(ag => {
            if (ag.data_compromisso.split('T')[0] !== data) return false;

            const agStart = horaParaMinutos(ag.hora_compromisso);
            const agEnd = agStart + 60;
            const novaEnd = novaHora + duracao;

            return (novaHora < agEnd && novaEnd > agStart);
        });

        if (!ocupado) {
            sugestoes.push({ 
                hora: minutosParaHora(novaHora), 
                delta 
            });
        }

        if (sugestoes.length >= 2) break;
    }

    return sugestoes;
}

const sugestoes = gerarSugestoes(dataSolicitada, horaMinutos, agenda, 60);

// Montar mensagem
let mensagemConflito = `${dataSolicitada} às ${formatarHora(horaSolicitada)} já tem:\n*"${conflito.nome_compromisso}"*\n\nQue tal?\n`;

if (sugestoes.length >= 1) {
    mensagemConflito += `1️⃣ ${dataSolicitada} às ${sugestoes[0].hora}\n`;
}
if (sugestoes.length >= 2) {
    mensagemConflito += `2️⃣ ${dataSolicitada} às ${sugestoes[1].hora}\n`;
}

mensagemConflito += `3️⃣ Cancelar agendamento`;
// ===== TESTE MANUAL =====
console.log('🧪 Testando gerarSugestoes():');
const testeSugestoes = gerarSugestoes(
    '2026-06-02',
    840,  // 14:00
    [{
        data_compromisso: '2026-06-02T14:00:00',
        hora_compromisso: '14:00'
    }],
    60
);
console.log('Sugestões de teste:', JSON.stringify(testeSugestoes, null, 2));
// Retornar resposta
return [{
    json: {
        ...input,
        _skip_llm: true,
        _conflito: true,
        acao: 'RESPONDER',
        mensagens: [{ conteudo: mensagemConflito }],
        conflito_dados: {
            original_data: dataSolicitada,
            original_hora: horaSolicitada,
            conflito_nome: conflito.nome_compromisso,
            sugestoes: sugestoes
        }
    }
}];

// NOVO NÓ: "Verificar Resposta Agendamento"
// Coloque ANTES do Switch Decision
// Código JavaScript:

const input = $input.first().json;

// Verifica se tem campos faltando ou está em fluxo de perguntas
const camposFaltando = input.campos_faltando || [];
const fluxoEstado = input._fluxo_estado || 'normal';
const precisaAjuda = input.precisa_ajuda === true;
const usuarioConfirmou = ['1', 'sim', 'confirmar'].includes(String(input.mensagem).toLowerCase());

// CASO 1: Usuário respondeu com dados faltantes
if (camposFaltando.length > 0) {
  console.log('📝 Ainda faltam campos - continuar conversa');
  return [{
    json: {
      ...input,
      acao: 'RESPONDER',
      mensagem: input.resposta_sugerida || `Qual ${camposFaltando[0]}?`
    }
  }];
}

// CASO 2: Usuário confirmou agendamento
if (fluxoEstado === 'aguardando_confirmacao' && usuarioConfirmou) {
  console.log('✅ Usuário confirmou - REGISTRAR');
  return [{
    json: {
      ...input,
      acao: 'REGISTRAR',
      dados: {
        usuario_id: input.usuario_id,
        nome_compromisso: input.nome_compromisso,
        data_compromisso: input.data_formatada,
        hora_compromisso: input.hora_formatada,
        local: input.local,
        nome_cliente: input.nome_cliente,
        telefone_cliente: input.telefone_cliente
      }
    }
  }];
}

// CASO 3: É agendamento mas faltam dados - ir para IA perguntar
if (input.is_agendamento && precisaAjuda) {
  console.log('🤔 Agendamento com dados incompletos - IA vai perguntar');
  return [{
    json: {
      ...input,
      acao: 'RESPONDER'  // Switch vai pegar isso
    }
  }];
}

// CASO 4: Não é agendamento - responder normalmente
return [{ json: input }];

// ============================================
// NÓ DE PREPROCESSAMENTO - VERSÃO DEFINITIVA
// ============================================

const input = $input.first().json;
const mensagemUsuario = (input.mensagem || '').trim();
const msgLower = mensagemUsuario.toLowerCase();

console.log('=========================================');
console.log('📥 PREPROCESSAMENTO - INICIO');
console.log('Mensagem:', mensagemUsuario);
console.log('_fluxo_estado:', input._fluxo_estado);
console.log('_contexto_completo:', JSON.stringify(input._contexto_completo));
console.log('=========================================');

// ============================================
// 0. SE JÁ ESTAMOS EM UM FLUXO DE AGENDAMENTO (estado guardado)
// ============================================
let fluxoEstado = input._fluxo_estado || null;
let contextoParcial = input._contexto_completo || {};

if (fluxoEstado === 'aguardando_dados' && Object.keys(contextoParcial).length > 0) {
    console.log('🔄 Fluxo de agendamento em andamento');

    const camposObrigatorios = ['nome_compromisso', 'data', 'hora', 'local'];
    const faltando = camposObrigatorios.filter(campo => !contextoParcial[campo]);

    console.log('Campos faltando:', faltando);

    // Se o único campo faltando é 'local', usa a mensagem como endereço
    if (faltando.length === 1 && faltando[0] === 'local') {
        contextoParcial.local = mensagemUsuario;
        console.log(`✅ Local definido como: "${mensagemUsuario}"`);
    }

    const aindaFaltando = camposObrigatorios.filter(campo => !contextoParcial[campo]);

    if (aindaFaltando.length === 0) {
        fluxoEstado = 'aguardando_confirmacao';
        console.log('🎯 Todos os campos preenchidos - mudando para AGUARDANDO_CONFIRMACAO');
    } else {
        console.log(`⏳ Ainda faltam: ${aindaFaltando.join(', ')}`);
    }

    return [{
        json: {
            ...input,
            is_agendamento: true,
            precisa_ajuda: aindaFaltando.length > 0,
            campos_faltando: aindaFaltando,
            _fluxo_estado: fluxoEstado,
