function extrairLocal(msg) {
    if (!msg) return null;
    let texto = msg.replace(/^o endereço é\s+/i, '').replace(/^endereço\s+/i, '');
    const patterns = [
        /(?:na|em|para)\s+([^,;.!?]+(?:[;,.]\s*[^,;.!?]+)?)/i,
        /(Rua|Avenida|Av|Alameda|Praça|Travessa|Beco|Estrada|Sítio|Rodovia)\s+([^,;.!?]+)/i,
        /^([A-Z][a-z]+(\s+[A-Z][a-z]+)*\s+\d+)/,
        /^([a-z\u00C0-\u00FF]+(\s+[a-z\u00C0-\u00FF]+)*\s+\d+)/i
    ];
    for (const pattern of patterns) {
        const match = texto.match(pattern);
        if (match) {
            let endereco = match[1] || match[0];
            endereco = endereco.trim();
            if (endereco.length > 3 && endereco.length < 100) return endereco;
        }
    }
    if (texto.length < 50 && !texto.match(/^(1|sim|nao|ok|confirmar)/i)) return texto;
    return null;
}

function extrairTelefoneCliente(msg) {
    if (!msg) return null;
    const patterns = [ /\(?(\d{2})\)?\s*(\d{4,5})-?(\d{4})/, /\b(1[1-9]|2[1-9]|3[1-9]|4[1-9]|5[1-9]|6[1-9]|7[1-9]|8[1-9]|9[1-9])\d{8,9}\b/, /\b\d{10,11}\b/ ];
    for (const pattern of patterns) {
        const match = msg.match(pattern);
        if (match) {
            let telefone = match[0].replace(/\D/g, '');
            if (telefone.length >= 10 && telefone.length <= 11) return telefone;
        }
    }
    return null;
}

function extrairNomeCliente(msg) {
    if (!msg) return null;
    const palavrasIgnorar = ['fornecedor', 'cliente', 'paciente', 'profissional', 'pessoa', 'amigo', 'familia', 'empresa'];
    const palavrasFim = ['amanhã', 'amanha', 'hoje', 'às', 'as', 'telefone', 'fone', 'whatsapp', 'celular', 'email', 'em', 'na', 'no', 'para'];
    const lookahead = '(?=\\s*,?\\s*(?:' + palavrasFim.join('|') + '|$))';
    let match = msg.match(new RegExp('com\\s+([A-ZÀ-Ú][a-zà-ú]+\\s+[A-ZÀ-Ú][a-zà-ú]+)' + lookahead, 'i'));
    if (match && match[1]) {
        let nome = match[1].trim();
        for (const palavra of palavrasFim) {
            const idx = nome.toLowerCase().indexOf(palavra);
            if (idx > 0) nome = nome.substring(0, idx).trim();
        }
        const primeiraPalavra = nome.toLowerCase().split(' ')[0];
        if (!palavrasIgnorar.includes(primeiraPalavra) && nome.length > 2) return nome;
    }
    match = msg.match(new RegExp('com\\s+([A-ZÀ-Ú][a-zà-ú]+)' + lookahead, 'i'));
    if (match && match[1]) {
        let nome = match[1].trim();
        for (const palavra of palavrasFim) {
            const idx = nome.toLowerCase().indexOf(palavra);
            if (idx > 0) nome = nome.substring(0, idx).trim();
        }
        if (!palavrasIgnorar.includes(nome.toLowerCase()) && nome.length > 2) return nome;
    }
    return null;
}

function extrairData(msg) {
    if (!msg) return null;
    const hoje = new Date(); hoje.setHours(0,0,0,0);
    if (msgLower.includes('hoje')) return hoje.toISOString().split('T')[0];
    if (msgLower.includes('amanhã') || msgLower.includes('amanha')) {
        const amanha = new Date(hoje); amanha.setDate(amanha.getDate()+1);
        return amanha.toISOString().split('T')[0];
    }
    if (msgLower.includes('depois de amanhã') || msgLower.includes('depois de amanha')) {
        const depois = new Date(hoje); depois.setDate(depois.getDate()+2);
        return depois.toISOString().split('T')[0];
    }
    const diasMap = { 'domingo':0, 'segunda':1, 'terça':2, 'quarta':3, 'quinta':4, 'sexta':5, 'sábado':6, 'sabado':6 };
    for (const [dia, numero] of Object.entries(diasMap)) {
        if (msgLower.includes(dia)) {
            const proximoDia = new Date(hoje);
            let diasAdelantar = numero - proximoDia.getDay();
            if (diasAdelantar <= 0) diasAdelantar += 7;
            proximoDia.setDate(proximoDia.getDate() + diasAdelantar);
            return proximoDia.toISOString().split('T')[0];
        }
    }
    const matchDDMM = msg.match(/(\d{1,2})\/(\d{1,2})/);
    if (matchDDMM) {
        const dia = String(matchDDMM[1]).padStart(2,'0');
        const mes = String(matchDDMM[2]).padStart(2,'0');
        let ano = hoje.getFullYear();
        if (parseInt(mes) < hoje.getMonth()+1) ano++;
        return `${ano}-${mes}-${dia}`;
    }
    return null;
}

function extrairHora(msg) {
    if (!msg) return null;
    const patterns = [ /(\d{1,2}):(\d{2})/, /(\d{1,2})h(\d{2})/, /(\d{1,2})\s*h(?:oras?)?/i, /às\s+(\d{1,2})(?:\s*h(?:oras?)?)?/i ];
    for (const pattern of patterns) {
        const match = msg.match(pattern);
        if (match) {
            let hora = String(match[1]).padStart(2,'0');
            let minuto = match[2] ? String(match[2]).padStart(2,'0') : '00';
            if (parseInt(hora) >=0 && parseInt(hora) <=23) return `${hora}:${minuto}:00`;
        }
    }
    return null;
}

function extrairNomeCompromisso(msg) {
    if (!msg) return null;
    const tipos = ['reunião', 'reuniao', 'consulta', 'entrega', 'visita', 'evento', 'encontro', 'compromisso'];
    for (const tipo of tipos) {
        if (msgLower.includes(tipo)) {
            const matchCom = msg.match(new RegExp(`${tipo}\\s+com\\s+([A-ZÀ-Ú][a-zà-ú]+(?:\\s+[A-ZÀ-Ú][a-zà-ú]+)?)`, 'i'));
            if (matchCom && matchCom[1]) {
                let nome = `${tipo.charAt(0).toUpperCase() + tipo.slice(1)} com ${matchCom[1]}`;
                nome = nome.replace(/\s+(amanhã|amanha|hoje|às|as|telefone).*$/i, '');
                return nome;
            }
            let nome = tipo.charAt(0).toUpperCase() + tipo.slice(1);
            nome = nome.replace(/\s+(amanhã|amanha|hoje|às|as|telefone).*$/i, '');
            return nome;
        }
    }
    return 'Compromisso';
}

