    nome_cliente: dadosMesclados.nome_cliente,
    telefone_cliente: dadosMesclados.telefone_cliente,
    local: dadosMesclados.local,
    nome_compromisso: dadosMesclados.nome_compromisso,
    _fluxo_estado: dadosMesclados._fluxo_estado,
    _contexto_completo: dadosMesclados,
    _source: 'preparar_contexto_unificado',
    _timestamp: hoje.toISOString(),
    _processing_time_ms: Date.now()
};

// Propagar campos de coleta de contas
if (inputAtual._estado_coleta !== undefined) contextoFinal._estado_coleta = inputAtual._estado_coleta;
if (inputAtual._contas_selecionadas !== undefined) contextoFinal._contas_selecionadas = inputAtual._contas_selecionadas;
if (inputAtual._indice_atual !== undefined) contextoFinal._indice_atual = inputAtual._indice_atual;
if (inputAtual._contas_coletadas !== undefined) contextoFinal._contas_coletadas = inputAtual._contas_coletadas;

