console.log(`   _fluxo_estado: ${contextoFinal._fluxo_estado}`);
console.log('=========================================');

return [{ json: contextoFinal }];

// ============================================
// CONTROLE DE HORÁRIO COMERCIAL
// ============================================

const input = $input.first().json;
const agora = new Date();
const hora = agora.getHours();
const diaSemana = agora.getDay(); // 0=domingo, 6=sábado

console.log('=========================================');
console.log('⏰ CONTROLE DE HORÁRIO');
console.log(`Hora atual: ${hora}`);
console.log(`Dia da semana: ${diaSemana} (0=domingo, 6=sábado)`);
console.log('=========================================');

// Verifica se é horário comercial (8h às 18h, Segunda a Sexta)
const isHorarioComercial = (hora >= 8 && hora <= 18) && (diaSemana >= 1 && diaSemana <= 5);
// const isHorarioComercial = true; // DESCOMENTE ESTA LINHA PARA TESTAR (ignora horário)

if (!isHorarioComercial) {
    console.log(`⏭️ Fora do horário comercial (${hora}h). Execução ignorada.`);
    return []; // Retorna vazio, interrompe o fluxo
}

console.log(`✅ Horário comercial (${hora}h). Execução permitida.`);
return [{ json: input }];

// ============================================
// CONTROLE DE EXECUÇÃO - EVITAR PROCESSAMENTO MÚLTIPLO
// ============================================

const hoje = new Date();
const hojeStr = hoje.toISOString().split('T')[0];
const horaAtual = hoje.getHours();
const minutoAtual = hoje.getMinutes();

console.log('=========================================');
console.log('⏰ CONTROLE DE EXECUÇÃO');
console.log(`Data/Hora: ${hojeStr} ${horaAtual}:${minutoAtual}`);
console.log('=========================================');

// Controle em memória para evitar execuções duplicadas no mesmo minuto
if (typeof global === 'undefined') {
    var global = {};
}

if (!global.ultimaExecucaoLembrete) {
    global.ultimaExecucaoLembrete = {};
}

const chaveExecucao = `${hojeStr}_${horaAtual}_${Math.floor(minutoAtual / 5) * 5}`; // Agrupa a cada 5 minutos

if (global.ultimaExecucaoLembrete[chaveExecucao]) {
    console.log(`⏭️ Pular execução: já processada neste intervalo (${chaveExecucao})`);
    console.log(`   Última execução: ${global.ultimaExecucaoLembrete[chaveExecucao]}`);
    return []; // Retorna vazio para parar o fluxo
}

// Marca esta execução
global.ultimaExecucaoLembrete[chaveExecucao] = new Date().toISOString();
console.log(`✅ Execução permitida - marcando: ${chaveExecucao}`);

// Limpa execuções antigas (mais de 1 hora)
for (const key in global.ultimaExecucaoLembrete) {
    const dataExecucao = new Date(global.ultimaExecucaoLembrete[key]);
    if (Date.now() - dataExecucao.getTime() > 60 * 60 * 1000) {
        delete global.ultimaExecucaoLembrete[key];
        console.log(`🧹 Limpando execução antiga: ${key}`);
    }
}

// Continua com o fluxo normal
return $input.all();

// ============================================
