        console.log('✅ Local do Preprocessamento:', preprocessNode.local);
    }
    if (preprocessNode.data_formatada && !dadosAgendamento.data_compromisso) {
        dadosAgendamento.data_compromisso = preprocessNode.data_formatada;
    }
    if (preprocessNode.hora_formatada && !dadosAgendamento.hora_compromisso) {
        dadosAgendamento.hora_compromisso = preprocessNode.hora_formatada;
    }
