}
if (!dadosAgendamento.nome_cliente && input.nome_cliente) {
    dadosAgendamento.nome_cliente = input.nome_cliente;
}
if (!dadosAgendamento.local && input.local) {
    dadosAgendamento.local = input.local;
}
if (!dadosAgendamento.data_compromisso && input.data_compromisso) {
    dadosAgendamento.data_compromisso = input.data_compromisso;
}
if (!dadosAgendamento.hora_compromisso && input.hora_compromisso) {
    dadosAgendamento.hora_compromisso = input.hora_compromisso;
}
if (!dadosAgendamento.nome_compromisso && input.nome_compromisso) {
    dadosAgendamento.nome_compromisso = input.nome_compromisso;
}

// ============================================
// DECLARAR VARIÁVEIS (COM NOME DO CLIENTE)
// ============================================

const nomeCompromisso = dadosAgendamento.nome_compromisso || input.summary || 'Compromisso';
const local = dadosAgendamento.local || input.location || 'Local não informado';
const nomeCliente = dadosAgendamento.nome_cliente || 'Não informado';
const telefoneCliente = dadosAgendamento.telefone_cliente || dadosAgendamento.telefone || 'Não informado';
