console.log(`   local: ${local}`);
console.log(`   nome_cliente: ${nomeCliente}`);
console.log(`   telefone_cliente: ${telefoneCliente}`);
console.log(`   data: ${dataCompromisso}`);
console.log(`   hora: ${horaCompromisso}`);

// ============================================
// MONTAR MENSAGEM (COM NOME DO CLIENTE)
