const mensagem = `✅ *Agendamento confirmado!*

*${nomeCompromisso}*
👤 Cliente: ${nomeCliente}
📍 ${local}
📞 Telefone: ${telefoneCliente}
📅 ${dataCompromisso} às ${horaCompromisso}

📅 *Link do evento:* ${input.htmlLink || 'Ver no Google Calendar'}

1️⃣ Ver agenda
2️⃣ Agendar outro
3️⃣ Cancelar`;

// Telefone do MEI
let telefone = dadosAgendamento.telefone_mei || dadosAgendamento.telefone || '5511900000001';

console.log('📤 Mensagem de confirmação criada:');
console.log(mensagem);
