// Nó: Verificar Token OAuth
const input = $input.first().json;

if (input.intent !== 'schedule') return { json: input };

// ============================================
// 🔧 MOCK PARA TESTE - REMOVER QUANDO OAuth ESTIVER PRONTO
// ============================================
