if (USE_MOCK && MOCK_USERS.includes(Number(input.usuario_id || input.id))) {
    console.log(`🧪 MOCK: Token OAuth válido para usuário ${input.usuario_id}`);

    // Mantém a mensagem que já veio do nó anterior
