    input.has_google_calendar = true;
    input.google_token_valid = true;

    return { json: input };
}
// ============================================

const OATH_SERVICE_URL = 'http://data-svc:8000';

try {
    const status = await $http.get(`${OATH_SERVICE_URL}/oauth/status`, {
        qs: { user_id: input.usuario_id }
    });

    input.has_google_calendar = status.json.authorized === true;
    input.google_token_valid = status.json.token_valid || false;

    if (!input.has_google_calendar) {
        input.mensagem_whatsapp = `🔐 *Para agendar automaticamente, conecte sua agenda Google.*\n\n` +
