            `Depois de autorizar, posso criar eventos automaticamente para você.\n\n` +
            `1️⃣ Quero conectar agora\n` +
            `2️⃣ Agendar manualmente\n` +
            `3️⃣ Depois`;

        input.skip_event_creation = true;
    }

} catch (error) {
    console.error('❌ Erro ao verificar token:', error.message);
    input.has_google_calendar = false;
}

return { json: input };

