// ============================================
// HELPER: Converter data para SQL
// ============================================
function converterDataParaSQL(dataStr) {
    if (!dataStr || dataStr === '' || dataStr === 'null' || dataStr === null) {
        return 'NULL::date';
    }

    dataStr = String(dataStr).trim();

    if (dataStr.match(/^\d{4}-\d{2}-\d{2}$/)) {
        return `'${dataStr}'::date`;
    }

    if (dataStr.match(/^\d{2}\/\d{2}\/\d{4}$/)) {
        const partes = dataStr.split('/');
        const resultado = `${partes[2]}-${partes[1]}-${partes[0]}`;
        return `'${resultado}'::date`;
    }

    if (dataStr.match(/^\d{2}\/\d{2}\/\d{2}$/)) {
        const partes = dataStr.split('/');
        const ano = `20${partes[2]}`;
        const resultado = `${ano}-${partes[1]}-${partes[0]}`;
        return `'${resultado}'::date`;
    }

    return 'NULL::date';
}

// ============================================
// HELPER: Converter hora para SQL
// ============================================
function converterHoraParaSQL(horaStr) {
    if (!horaStr || horaStr === '' || horaStr === 'null' || horaStr === null) {
        return 'NULL::time';
    }

    horaStr = String(horaStr).trim();

    if (horaStr.match(/^\d{2}:\d{2}:\d{2}$/)) {
        return `'${horaStr}'::time`;
    }

    if (horaStr.match(/^\d{1,2}:\d{2}$/)) {
        return `'${horaStr}:00'::time`;
    }

    if (horaStr.match(/^\d{1,2}h\d{2}$/)) {
        const partes = horaStr.split('h');
        const resultado = `${partes[0].padStart(2, '0')}:${partes[1]}:00`;
        return `'${resultado}'::time`;
    }

    return 'NULL::time';
}

