                _agendamento_original: agendamentoOriginal
            },
            acao: "RESPONDER",
            _skip_llm: true,
            mensagem_whatsapp: mensagemConfirmacao
        }
    }];
}

if (estado === 'confirmar') {
    console.log('📌 CONFIRMAR');
    const resposta = (input.mensagem || '').toLowerCase().trim();
    const confirmado = resposta === '1' || resposta === 'sim' || resposta === 'confirmar';
    if (!confirmado) {
        return [{
            json: {
                ...input,
                _estado_reagendamento: null,
                _estado_para_salvar: null,
                acao: "RESPONDER",
                _skip_llm: true,
                mensagem_whatsapp: "Ok, reagendamento cancelado."
            }
        }];
    }
    console.log(`✅ Reagendado para ${input._nova_data} ${input._nova_hora}`);
    return [{
        json: {
            ...input,
            _estado_reagendamento: null,
            _estado_para_salvar: null,
            acao: "RESPONDER",
            _skip_llm: true,
            mensagem_whatsapp: "✅ Reagendado. 📅"
        }
    }];
}

console.log(`⚠️ Estado não reconhecido: ${estado}`);
return [{ json: input }];

// ============================================
// BUSCAR AGENDAMENTOS REAGENDAR - CORRIGIDO
// ============================================

const input = $input.first().json;

if (input._acao_reagendamento !== 'reagendar') {
    return [{ json: input }];
}

// 🔁 MOCK: Usa o _nome_mencionado extraído (sem "para")
const nomeExtraido = input._nome_mencionado || 'Compromisso';

// Limpar o nome se necessário
const nomeLimpo = nomeExtraido
    .replace(/\s+(para|amanhã|amanha|hoje|sexta|segunda|terça|quarta|quinta|sábado|sabado|domingo)\b.*/i, '')
    .split(' ')
    .map(p => p.charAt(0).toUpperCase() + p.slice(1).toLowerCase())
    .join(' ');

const agendamentoFicticio = {
    id: 999,
