    data_compromisso: '2026-06-02T00:00:00.000Z',  // Amanhã
    hora_compromisso: '10:00:00'  // 10h
};

console.log('📋 [MOCK] Nome extraído:', nomeExtraido);
console.log('✨ [MOCK] Nome limpo:', nomeLimpo);
console.log('📋 [MOCK] Retornando agendamento:', agendamentoFicticio.nome_compromisso);

return [{
    json: {
        ...input,
        agendamentos: [agendamentoFicticio]
    }
}];

const input = $input.first().json;
console.log('=== ESTADO RECEBIDO ===');
