parameters.query:
SELECT COALESCE(
    (SELECT estado FROM sessao_estado WHERE session_id = '{{ $json.session_id }}' LIMIT 1),
    '{}'::jsonb
) AS estado;

parameters.jsCode:
// Resultado da query (estado salvo em sessao_estado)
const estadoResult = $input.first().json;
let estadoSalvo = estadoResult.estado || {};

// Input original (Mesclar Dados)
const inputOriginal = $('Mesclar Dados').first().json;

if (estadoSalvo && Object.keys(estadoSalvo).length > 0) {
    // Reagendamento
    if (estadoSalvo._estado_reagendamento) {
        inputOriginal._estado_reagendamento = estadoSalvo._estado_reagendamento;
        inputOriginal._agendamento_original   = estadoSalvo._agendamento_original;
        inputOriginal._nova_data              = estadoSalvo._nova_data;
        inputOriginal._nova_hora              = estadoSalvo._nova_hora;
        console.log('🔄 Estado de reagendamento restaurado:', estadoSalvo._estado_reagendamento);
    }
    // Cancelamento
    if (estadoSalvo._acao_cancelamento) {
        inputOriginal._acao_cancelamento      = estadoSalvo._acao_cancelamento;
        inputOriginal._agendamentoParaDeletar = estadoSalvo._agendamentoParaDeletar;
        console.log('🔄 Estado de cancelamento restaurado:', estadoSalvo._acao_cancelamento);
    }
} else {
    console.log('ℹ️ Nenhum estado salvo; usando o input atual.');
}

return [{ json: inputOriginal }];

// ============================================
// Preparar Query SQL - COM VALIDAÇÃO DE SEGURANÇA
// ============================================
const input = $input.first().json;

// 🛡️ Proteção: só gera query se houver estado para salvar
if (!input._estado_para_salvar) {
    console.log('⚠️ Nenhum estado para salvar. Pulando query.');
    return []; // Retorna vazio → o nó Postgres não será executado
}

// Monta a string do estado (escapando para SQL)
const estadoStr = JSON.stringify(input._estado_para_salvar)
    .replace(/'/g, "''")
    .replace(/\\/g, "\\\\");

const sql = `
INSERT INTO sessao_estado (session_id, estado, updated_at)
VALUES ('${input.session_id}', '${estadoStr}'::jsonb, NOW())
ON CONFLICT (session_id) DO UPDATE 
SET estado = EXCLUDED.estado, updated_at = NOW();
`;

input._query_sql = sql;
return [{ json: input }];

const saida = $input.first().json;
console.log('SAÍDA DO PROCESSAR REAGENDAMENTO:', JSON.stringify(saida, null, 2));
return [{ json: saida }];

const input = $input.first().json;
const msg = (input.mensagem || '').toLowerCase().trim();

console.log('🔍 Detectando intenção:', msg);

// ============================================
// 0. PRIORIDADE: continuação de fluxo em andamento
//    (estado restaurado de sessao_estado)
// ============================================
if (input._acao_cancelamento) {
    console.log('↩️ Continuação de CANCELAMENTO:', input._acao_cancelamento);
    return [{ json: { ...input, _intencao: 'cancelamento', _acao: 'cancelar' } }];
}
if (input._estado_reagendamento) {
    console.log('↩️ Continuação de REAGENDAMENTO:', input._estado_reagendamento);
    return [{ json: { ...input, _intencao: 'reagendamento', _acao: 'reagendar', _acao_reagendamento: 'reagendar' } }];
}

// ============================================
// 1. CANCELAMENTO (nova intenção)
// ============================================
let intencao = 'agendamento_normal';
let detalhes = {};

const isCancel = /cancela|remove|deleta|apaga|desmarca|tira|desmarcar/.test(msg);
if (isCancel) {
    intencao = 'cancelamento';
    const match = msg.match(/cancela\s+(?:a\s+)?(?:o\s+)?(.+?)(?:\s+de|$)/i);
    detalhes.nome_mencionado = match ? match[1].trim() : null;
}

// ============================================
// 2. REAGENDAMENTO
// ============================================
const isReagendar = /reagendar|remarcar|mudar|alterar|trocar|adiar|transferir/.test(msg);
if (isReagendar && !isCancel) {
    intencao = 'reagendamento';
    const match = msg.match(/(?:reagendar|remarcar)\s+(?:o\s+)?(?:compromisso\s+)?(.+?)(?=\s+(?:para|dia|às|$))/i);
    detalhes.nome_mencionado = match ? match[1].trim() : null;
}

return [{
    json: {
        ...input,
        _intencao: intencao,
        _detalhes_intencao: detalhes,
        _acao: intencao === 'cancelamento' ? 'cancelar'
             : intencao === 'reagendamento' ? 'reagendar' : null,
        _acao_reagendamento: intencao === 'reagendamento' ? 'reagendar' : (input._acao_reagendamento || null)
    }
}];

// ============================================
// PROCESSAR REAGENDAMENTO - V3 (3 turnos, sem switch)
// Gerencia internamente salvar/restaurar estado via _rota
// ============================================

const input = $input.first().json;
const USE_MOCK = true; // Mude para false em produção

// Recupera estado salvo anteriormente (vindo de sessao_estado via Mesclar Estado com Input)
let estado = input._estado_reagendamento || null;
let agendamentoOriginal = input._agendamento_original || null;
let novaData = input._nova_data || null;
let novaHora = input._nova_hora || null;

console.log(`🔍 PROCESSAR REAGENDAMENTO - Estado: ${estado}`);

// ============================================
// FUNÇÕES AUXILIARES
// ============================================
function extrairData(mensagem) {
    const hoje = new Date(); hoje.setHours(0,0,0,0);
    const msgLow = mensagem.toLowerCase();
    if (msgLow.includes('hoje')) return hoje.toISOString().split('T')[0];
    if (msgLow.includes('amanhã')) {
        const amanha = new Date(hoje); amanha.setDate(amanha.getDate()+1);
        return amanha.toISOString().split('T')[0];
    }
    if (msgLow.includes('depois de amanhã')) {
        const depois = new Date(hoje); depois.setDate(depois.getDate()+2);
        return depois.toISOString().split('T')[0];
    }
    const diasMap = {
        'domingo':0, 'segunda':1, 'terça':2, 'quarta':3,
        'quinta':4, 'sexta':5, 'sábado':6, 'sabado':6
    };
    for (const [dia, num] of Object.entries(diasMap)) {
        if (msgLow.includes(dia)) {
            const proximo = new Date(hoje);
            let diff = num - proximo.getDay();
            if (diff <= 0) diff += 7;
            proximo.setDate(proximo.getDate() + diff);
            return proximo.toISOString().split('T')[0];
        }
    }
    const match = mensagem.match(/(\d{1,2})\/(\d{1,2})(?:\/(\d{4}))?/);
    if (match) {
        let dia = parseInt(match[1]), mes = parseInt(match[2]);
        let ano = match[3] ? parseInt(match[3]) : hoje.getFullYear();
        if (mes < hoje.getMonth()+1 && !match[3]) ano++;
        return `${ano}-${String(mes).padStart(2,'0')}-${String(dia).padStart(2,'0')}`;
    }
    return null;
}

function extrairHora(mensagem) {
    const match = mensagem.match(/(\d{1,2}):(\d{2})|(\d{1,2})h(\d{2})?/);
    if (match) {
        let hora = match[1] || match[3];
        let minuto = match[2] || match[4] || '00';
        return `${String(hora).padStart(2,'0')}:${String(minuto).padStart(2,'0')}:00`;
    }
    return null;
}

// ============================================
// DETECÇÃO DE NOVO REAGENDAMENTO (primeiro turno)
// ============================================
if (!estado) {
    const msg = (input.mensagem || '').toLowerCase();
    const isReagendar = /reagendar|remarcar|mudar|alterar|adiar|transferir/.test(msg);

    if (!isReagendar) {
        return [{ json: input }];
    }

    console.log('🔄 Novo reagendamento detectado');

    // Buscar agendamentos (mock ou real)
    let agendamentos = [];
    if (USE_MOCK) {
        agendamentos = [{
            id: 999,
            nome_compromisso: input._nome_mencionado || 'Reunião com João',
            data_compromisso: '2026-06-02T00:00:00.000Z',
            hora_compromisso: '10:00:00'
        }];
    } else {
        try {
            const usuarioId = input.usuario_id || input.id;
            const resp = await $http.get(`http://data-svc:8000/usuarios/${usuarioId}/agendamentos`, {
                qs: { semana: 'atual' },
                headers: { 'X-API-Key': $env.DATA_SVC_API_KEY }
            });
            agendamentos = resp.body?.agendamentos || [];
        } catch(e) {
            console.error('❌ Erro ao buscar agendamentos:', e.message);
        }
    }

    // Encontrar agendamento pelo nome mencionado
    let agendamento = null;
    const nomeMencionado = input._nome_mencionado || '';
    if (nomeMencionado) {
        agendamento = agendamentos.find(ag => 
            ag.nome_compromisso.toLowerCase().includes(nomeMencionado.toLowerCase())
        );
    }
    if (!agendamento && agendamentos.length === 1) {
        agendamento = agendamentos[0];
    }

    if (!agendamento) {
        return [{
            json: {
                ...input,
                acao: 'RESPONDER',
                _skip_llm: true,
                mensagem_whatsapp: 'Não encontrei nenhum compromisso futuro para reagendar.',
                _estado_para_salvar: null,
                _rota: 'deletar'
            }
        }];
    }

    const dataOriginal = agendamento.data_compromisso.split('T')[0];
    const horaOriginal = agendamento.hora_compromisso.substring(0, 5);

    // Primeiro turno: pedir nova data/hora e salvar estado
    const estadoSalvar = {
        _estado_reagendamento: 'aguardando_nova_data',
        _agendamento_original: agendamento
    };

    return [{
        json: {
            ...input,
            acao: 'RESPONDER',
            _skip_llm: true,
            mensagem_whatsapp: `Encontrei *"${agendamento.nome_compromisso}"* em ${dataOriginal} às ${horaOriginal}.\n\nQual a nova data e hora? (ex: sexta às 14h)`,
            ...estadoSalvar,
            _estado_para_salvar: estadoSalvar,
            _rota: 'salvar'
        }
    }];
}

// ============================================
// TURNO 2: aguardando nova data/hora
// ============================================
if (estado === 'aguardando_nova_data') {
    if (!agendamentoOriginal) {
        return [{
            json: {
                ...input,
                acao: 'RESPONDER',
                _skip_llm: true,
                mensagem_whatsapp: 'Desculpe, perdi o compromisso original. Pode repetir?',
                _estado_para_salvar: null,
                _rota: 'deletar'
            }
        }];
    }

    const mensagemUsuario = input.mensagem || '';
    let novaDataExtraida = extrairData(mensagemUsuario);
    let novaHoraExtraida = extrairHora(mensagemUsuario);

    if (!novaDataExtraida) {
        return [{
            json: {
                ...input,
                acao: 'RESPONDER',
                _skip_llm: true,
                mensagem_whatsapp: 'Não entendi a data. Use "amanhã", "sexta-feira" ou "10/06".'
            }
        }];
    }

    if (!novaHoraExtraida) {
        novaHoraExtraida = '12:00:00';
        console.log('⏰ Hora padrão 12:00');
    }

    const dataOriginal = agendamentoOriginal.data_compromisso.split('T')[0];
    const horaOriginal = agendamentoOriginal.hora_compromisso.substring(0, 5);
    const novaHoraFormatada = novaHoraExtraida.substring(0, 5);

    const estadoSalvar = {
        _estado_reagendamento: 'confirmar',
        _agendamento_original: agendamentoOriginal,
        _nova_data: novaDataExtraida,
        _nova_hora: novaHoraExtraida
    };

    return [{
        json: {
            ...input,
            _estado_reagendamento: 'confirmar',
            _agendamento_original: agendamentoOriginal,
            _nova_data: novaDataExtraida,
            _nova_hora: novaHoraExtraida,
            acao: 'RESPONDER',
            _skip_llm: true,
            mensagem_whatsapp: `Vê se eu entendi certo:\n\n*"${agendamentoOriginal.nome_compromisso}"*\nANTES: ${dataOriginal} às ${horaOriginal}\nDEPOIS: ${novaDataExtraida} às ${novaHoraFormatada}\n\nConfirma?\n1️⃣ Sim\n2️⃣ Ajustar`,
            _estado_para_salvar: estadoSalvar,
            _rota: 'salvar'
        }
    }];
}

// ============================================
// TURNO 3: confirmar reagendamento
// ============================================
if (estado === 'confirmar') {
    const resposta = (input.mensagem || '').toLowerCase().trim();
    const confirmado = resposta === '1' || resposta === 'sim' || resposta === 'confirmar';

    if (!confirmado) {
        return [{
            json: {
                ...input,
                acao: 'RESPONDER',
                _skip_llm: true,
                mensagem_whatsapp: 'Ok, reagendamento cancelado.',
                _estado_reagendamento: null,
                _estado_para_salvar: null,
                _rota: 'deletar'
            }
        }];
    }

    // Executar o reagendamento (DELETE do antigo + INSERT do novo)
    if (!USE_MOCK) {
        try {
            const usuarioId = input.usuario_id || input.id;
            const agendamentoOriginalObj = input._agendamento_original;

            // Deletar o antigo
            await $http.request({
                method: 'DELETE',
                url: `http://data-svc:8000/usuarios/${usuarioId}/agendamentos/${agendamentoOriginalObj.id}`,
                headers: { 'X-API-Key': $env.DATA_SVC_API_KEY }
            });

            // Criar o novo
            await $http.request({
                method: 'POST',
                url: `http://data-svc:8000/usuarios/${usuarioId}/agendamentos`,
                body: {
                    nome_compromisso: agendamentoOriginalObj.nome_compromisso,
                    data_compromisso: input._nova_data,
                    hora_compromisso: input._nova_hora,
                    status: 'pendente'
                },
                headers: { 'X-API-Key': $env.DATA_SVC_API_KEY, 'Content-Type': 'application/json' }
            });
        } catch(e) {
            console.error('❌ Erro ao reagendar:', e.message);
            return [{
                json: {
                    ...input,
                    acao: 'RESPONDER',
                    _skip_llm: true,
                    mensagem_whatsapp: 'Deu erro ao reagendar. Tenta de novo?',
                    _estado_para_salvar: null,
                    _rota: 'deletar'
                }
            }];
        }
    }

    return [{
        json: {
            ...input,
            acao: 'RESPONDER',
            _skip_llm: true,
            mensagem_whatsapp: '✅ Reagendado. 📅',
            _estado_reagendamento: null,
            _estado_para_salvar: null,
            _rota: 'deletar'
        }
    }];
}

// Fallback
return [{ json: input }];

const input = $input.first().json;
const temEstado = input._estado_para_salvar !== undefined && input._estado_para_salvar !== null;

// Adiciona uma flag para roteamento
input._rota = temEstado ? 'salvar' : 'deletar';

return [{ json: input }];
